runIdempotent(requestId, UPSERT_CHANNEL_CONFIG, fingerprint, ChannelConfigResponse.class, () -> {
    long now = clock.millis();
    var existing = channelCapConfigRepository.lockByKey(channelKey);
    if (request.expectedVersion() == null) {
        if (existing.isPresent()) throw 409 "channel config already exists, expectedVersion required";
        channelCapConfigRepository.insert(channelKey, dailyCap, now);
    } else {
