    @Test
    @DisplayName("渠道额度不足返回 429：不创建预占、公告侧额度不消耗、失败不占幂等键")
    void apply_channelExhausted_returns429AndConsumesNothing() {
        createChannel("req-ch", "ch1", 1);
        createCampaign("req-c1", "c1", 10, 10, "ch1");

        apply("req-a1", "c1", "v1");
        // 渠道已满（公告额度仍充足）→ 429
